"use client";
import { useState } from "react";

// Add base64 strings here keyed by category slug
const CATEGORY_IMAGES: Record<string, string> = {
  "power-energy":       "data:image/jpeg;base64,", // Power & Energy
  "wireless-comms":     "data:image/jpeg;base64,", // Wireless & Comms
  "sensors":            "data:image/webp;base64,", // Sensors
  "input-devices":      "data:image/png;base64,", // Input Devices
  "motors-actuators":   "data:image/jpeg;base64,", // Motors & Actuators
  "connectors-cables":  "data:image/jpeg;base64,", // Connectors & Cables
  "audio-components":   "data:image/jpeg;base64,", // Audio Components
  "display-lighting":   "data:image/jpeg;base64,", // Display & Lighting
  "passive-components": "data:image/webp;base64,", // Passive Components
};

type Category = {
  id: string;
  slug: string;
  name: string;
  iconEmoji: string | null;
  tags: string[];
  _count: { posts: number; components: number };
};

export default function HomeCategoryLayout({ categories }: { categories: Category[] }) {
  const [activeSlug, setActiveSlug] = useState<string | null>(null);

  const left = categories.slice(0, 5);
  const right = categories.slice(5, 9);
  const activeCategory = categories.find((c) => c.slug === activeSlug) ?? null;

  return (
    <>
      {/* Floating top-right nav for home page */}
      <div className="home-float-nav">
        <a href="/new-thread" className="nav-link">New Thread</a>
        <a href="/admin" className="nav-link">Admin</a>
      </div>

      <div className="main-layout">
      {/* LEFT COLUMN */}
      <div className="col-left">
        {left.map((cat) => (
          <a
            key={cat.id}
            className={`cat-cluster${activeSlug === cat.slug ? " active" : ""}`}
            href={`/category/${cat.slug}`}
            onMouseEnter={() => setActiveSlug(cat.slug)}
            onMouseLeave={() => setActiveSlug(null)}
          >
            <span className="cat-name">{cat.iconEmoji} {cat.name}</span>
            <span className="cat-tags">{cat.tags.join(" · ")}</span>
            <span className="cat-count">{cat._count.posts} threads</span>
          </a>
        ))}
      </div>

      {/* CENTER LOGO */}
      <div className="center-logo">
        <div className={`logo-image-wrapper${activeSlug ? " active" : ""}`}>
          {/* Default logo */}
          <div className="logo-default" style={{ opacity: activeSlug ? 0 : 1 }}>
           <img src="data:image/png;base64," alt="" />
          </div>

          {/* Per-category images */}
          {categories.map((cat) =>
            CATEGORY_IMAGES[cat.slug] ? (
              <div
                key={cat.slug}
                className={`logo-category-img${activeSlug === cat.slug ? " visible" : ""}`}
              >
                <img src={CATEGORY_IMAGES[cat.slug]} alt={cat.name} />
              </div>
            ) : null
          )}

          {/* Fallback emoji for categories without an image */}
          {activeCategory && !CATEGORY_IMAGES[activeCategory.slug] && (
            <div className="logo-category-img visible">
              <span style={{ fontSize: "5rem" }}>{activeCategory.iconEmoji}</span>
            </div>
          )}
        </div>
        {/* <p className="logo-name">E-Wastepedia</p>
        <p className="logo-sub">Open Source E-Waste Encyclopedia</p> */}
      </div>

      {/* RIGHT COLUMN */}
      <div className="col-right">
        {right.map((cat) => (
          <a
            key={cat.id}
            className={`cat-cluster${activeSlug === cat.slug ? " active" : ""}`}
            href={`/category/${cat.slug}`}
            onMouseEnter={() => setActiveSlug(cat.slug)}
            onMouseLeave={() => setActiveSlug(null)}
          >
            <span className="cat-name">{cat.iconEmoji} {cat.name}</span>
            <span className="cat-tags">{cat.tags.join(" · ")}</span>
            <span className="cat-count">{cat._count.posts} threads</span>
          </a>
        ))}
      </div>
    </div>
    </>
  );
}
